  V3(-1,-1,-1), V3( 1,-1,-1), V3( 1, 1,-1), V3(-1, 1,-1), // back
  V3(-1,-1, 1), V3( 1,-1, 1), V3( 1, 1, 1), V3(-1, 1, 1),  // front
];

// ---- Face triangles (indices) ----
const faces = [
  [0,1,2],[0,2,3], // back
  [4,6,5],[4,7,6], // front
  [0,4,5],[0,5,1], // bottom
  [2,6,7],[2,7,3], // top
  [1,5,6],[1,6,2], // right
  [4,0,3],[4,3,7], // left
];

// ---- Light source (moves around) ----
let light = V3(0.7, -0.6, 0.3);
let lightSpeed = 0.012;

// ---- Camera ----
const FOV = 1.0;
let rotX = 0.5, rotY = 0.3;

// ---- Animation state ----
let paused = false, wireframe = false;
let lastTime = performance.now();
let frameCount = 0;
let fps = 0;
let fpsTimer = 0;

// ---- Key handlers ----
document.addEventListener('keydown', e => {
  if (e.key === 'p' || e.key === 'P') paused = !paused;
  if (e.key === 'w' || e.key === 'W') wireframe = !wireframe;
});

function updateLight(t) {
  light.x = Math.sin(t * lightSpeed) * 0.8 + 0.2;
  light.y = Math.cos(t * lightSpeed) * 0.8 - 0.6;
  light.z = Math.sin(t * lightSpeed * 0.7) * 0.8 + 0.3;
}

function project(v) {
  const x = v.x * FOV / (v.z + FOV);
  const y = v.y * FOV / (v.z + FOV);
  return { x, y };
}

function render() {
  // update FPS
  const now = performance.now();
  frameCount++;
  if (now - fpsTimer >= 1000) {
    fps = frameCount;
    frameCount = 0;
    fpsTimer = now;
  }
  ctx.fillStyle = '#111';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // light direction for Lambert
  const lightDir = normalize(light);

  // rotate cube
  const R = {
    rotX(v) { return V3(v.x, v.y*Math.cos(rotX)-v.z*Math.sin(rotX), v.y*Math.sin(rotX)+v.z*Math.cos(rotX)); },
    rotY(v) { return V3(v.x*Math.cos(rotY)+v.z*Math.sin(rotY), v.y, -v.x*Math.sin(rotY)+v.z*Math.cos(rotY)); },
  };
  const rot = v => R.rotY(R.rotX(v));

  // project
  const P = v => project(rot(v));

  // Gouraud: per-vertex lighting then interpolate
  const coloredVerts = cubeVerts.map(v => {
    // transform normal by rotation
    const n = V3(v.x, v.y, v.z);
    const lightD = normalize(sub(light, V3(0,0,0)));
    // Lambert I = max(0, dot(n, l))
    const lambert = Math.max(0, dot(n, lightD)) * 0.55;
    // diffuse color
    const R = lambert * 0.9 + 0.05;
    const G = lambert * 0.4 + 0.05;
    const B = lambert * 0.1 + 0.05;
    return { ...v, r: R, g: G, b: B };
  });

