    const v0 = coloredVerts[face[0]];
    const v1 = coloredVerts[face[1]];
    const v2 = coloredVerts[face[2]];
    const p0 = P(v0);
    const p1 = P(v1);
    const p2 = P(v2);
    const area = (p1.x-p0.x)*(p2.y-p0.y)-(p1.y-p0.y)*(p2.x-p0.x);

    if (wireframe) {
      ctx.strokeStyle = '#333';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(p0.x, p0.y); ctx.lineTo(p1.x, p1.y);
      ctx.lineTo(p2.x, p2.y); ctx.closePath();
      ctx.stroke();
      continue;
    }

    // backface culling
    if (area < 0) continue;

    // interpolate color across triangle
    const color = (x, y) => {
      // barycentric
      const f1x = p1.x - p0.x, f1y = p1.y - p0.y;
      const f2x = p2.x - p1.x, f2y = p2.y - p1.y;
      const f3x = p0.x - p2.x, f3y = p0.y - p2.y;
      const inv = 1.0 / (f1x*(f2y-f3y) + f1y*(f3x-f2x));
      const v = ((p2.y-p1.y)*(x-p1.x) + (p1.x-p2.x)*(y-p1.y)) * inv;
      const w = ((p2.y-p0.y)*(x-p0.x) + (p0.x-p2.x)*(y-p0.y)) * inv;
      const u = 1.0 - v - w;
      return {
        r: u*v0.r + v*v1.r + w*v2.r,
        g: u*v0.g + v*v1.g + w*v2.g,
        b: u*v0.b + v*v1.b + w*v2.b,
      };
    };

