    gradient.addColorStop(0, `rgb(${v0.r*255},${v0.g*255},${v0.b*255})`);
    gradient.addColorStop(1, `rgb(${v2.r*255},${v2.g*255},${v2.b*255})`);
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.moveTo(p0.x, p0.y); ctx.lineTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y); ctx.closePath();
    ctx.fill();
  }

